static int read_file(const char *path,unsigned char **out,size_t size){FILE *f=fopen(path,"rb");if(!f)return -1;unsigned char *p=malloc(size);if(!p){fclose(f);return -1;}size_t n=fread(p,1,size,f);int bad=n!=size||fgetc(f)!=EOF||ferror(f);fclose(f);if(bad){free(p);return -1;}*out=p;return 0;}
static TaxiTrafficActor actor_from_ram(const unsigned char *ram){const unsigned char *p=ram+0xf4;TaxiTrafficActor a={0};a.flags=u32(p);a.type=u32(p+4);a.countdown=s32(p+0x10);a.x=s32(p+0x14);a.y=s32(p+0x18);a.z=s32(p+0x1c);a.heading=s32(p+0x20);a.route=131;a.path.distance=s32(p+0x28);a.path.x=s32(p+0x34);a.path.z=s32(p+0x38);a.path.heading=(uint16_t)u32(p+0x3c);a.impulse_x=s32(p+0x40);a.offset_x=s32(p+0x44);a.impulse_z=s32(p+0x48);a.offset_z=s32(p+0x4c);a.collision_timer=s32(p+0x58);return a;}
int main(int argc,char **argv){if(argc!=5){fprintf(stderr,"usage: probe before.ewram after.ewram road.ctp driving.ctr\n");return 2;}unsigned char *before_ram=NULL,*after_ram=NULL,*bundle=NULL;if(read_file(argv[1],&before_ram,0x40000)||read_file(argv[2],&after_ram,0x40000)){fprintf(stderr,"could not read full 256 KiB EWRAM checkpoints\n");free(before_ram);free(after_ram);return 3;}TaxiTrafficActor source_before=actor_from_ram(before_ram),source_after=actor_from_ram(after_ram);free(before_ram);free(after_ram);TaxiAiPathAsset road={0};if(taxi_traffic_path_load(&road,argv[3])){fprintf(stderr,"could not load route131\n");return 4;}if(read_file(argv[4],&bundle,34504)||memcmp(bundle,"CTR1",4)){fprintf(stderr,"could not load source CTR1 driving tables\n");free(bundle);free(road.points);return 5;}TaxiTrig trig;taxi_trig_decode(&trig,bundle+4,bundle+8196);free(bundle);TaxiTrafficActor actor=source_before;if(taxi_traffic_path_initialize(road.points,road.count,actor.path.distance,&actor.path)){fprintf(stderr,"could not initialize native path state\n");free(road.points);return 6;}TaxiAcceleration player={0};player.gears.speed_544=22140;player.gears.scale_5cc=60;player.gears.ratios[0]=4096;player.gears.final_ratio=4096;player.gears.boost_75c=-1;TaxiTrafficGlobals globals={0};uint32_t rng=0;TaxiTrafficActorEffects effects={0};int heading=13688832>>12&4095;int rc=taxi_traffic_actor_follow(&actor,&road,&player,23086,-33528,trig.sine[heading],trig.cosine[heading],5,5,0,0,&globals,&rng,&effects);int path_match=actor.path.distance==source_after.path.distance&&actor.path.x==source_after.path.x&&actor.path.z==source_after.path.z&&actor.path.heading==source_after.path.heading;int actor_match=actor.flags==source_after.flags&&actor.countdown==source_after.countdown&&actor.x==source_after.x&&actor.y==source_after.y&&actor.z==source_after.z&&actor.heading==source_after.heading&&actor.collision_timer==source_after.collision_timer&&actor.impulse_x==source_after.impulse_x&&actor.impulse_z==source_after.impulse_z&&actor.offset_x==source_after.offset_x&&actor.offset_z==source_after.offset_z&&path_match;int event_match=rc==0&&effects.collision&&player.gears.speed_544==5535&&actor_match;printf("route=131 heading_index=%d trig=(%d,%d) taxi=(23086,-33528)\n",heading,trig.sine[heading],trig.cosine[heading]);printf("native rc=%d collision=%d speed=%d source_speed=5535 path=(%d,%d,%d,%u) source_path=(%d,%d,%d,%u) actor=(%d,%d) source_actor=(%d,%d) impulse=(%d,%d) source_impulse=(%d,%d) exact_actor=%s event_match=%s\n",rc,effects.collision,player.gears.speed_544,actor.path.distance,actor.path.x,actor.path.z,actor.path.heading,source_after.path.distance,source_after.path.x,source_after.path.z,source_after.path.heading,actor.x,actor.z,source_after.x,source_after.z,actor.impulse_x,actor.impulse_z,source_after.impulse_x,source_after.impulse_z,actor_match?"yes":"no",event_match?"yes":"no");free(road.points);return event_match?0:7;}
